UPDATE server_asset
SET name = #{name}, ip = #{ip}, port = #{port}, username = #{username},
    auth_type = #{authType}, password_encrypted = #{passwordEncrypted},
    private_key_encrypted = #{privateKeyEncrypted}, group_id = #{groupId},
    tags = #{tags}, is_active = #{isActive}
WHERE id = #{id}

UPDATE server_asset
SET last_check_time = #{lastCheckTime}, last_check_status = #{lastCheckStatus}
WHERE id = #{id}
